                <h1 id="introducao">Introdução</h1>
<p>API RESTful para controle e gestão de frotas de veículos, secretarias, perfis de acesso e autenticação JWT.</p>
<aside>
    <strong>URL base</strong>: <code>http://localhost:8000</code>
</aside>
<p>Esta documentação tem como objetivo fornecer todas as informações necessárias para trabalhar com nossa API.</p>
<aside>Conforme você rola a página, verá exemplos de código para interagir com a API em diferentes linguagens de programação na área escura à direita (ou como parte do conteúdo em dispositivos móveis).
Você pode alternar a linguagem usada nas abas no canto superior direito (ou no menu de navegação no canto superior esquerdo em dispositivos móveis).</aside>

                <h1 id="autenticacao-de-requisicoes">Autenticação de requisições</h1>
<p>Para autenticar requisições, inclua o cabeçalho <strong><code>Authorization</code></strong> com o valor <strong><code>"Bearer {SEU_TOKEN_DE_AUTH}"</code></strong>.</p>
<p>Todos os endpoints autenticados estão marcados com o selo <code>requer autenticação</code> na documentação abaixo.</p>
<p>Adicione o token retornado no login ou cadastro no cabeçalho: <code>Authorization: Bearer {SEU_TOKEN_DE_AUTH}</code>.</p>
            </div>
        </div>

